  var h = document.getElementById(id);
  var t = h ? h.textContent : '';
  return /\\S/.test(t || '') ? t : fallback;
}
function paintBoard() {
  paintMatchState();
  var root = document.querySelector('.scoreboard');
  if (!root) return;
  var a = parseInt((document.getElementById('f1') || {}).textContent, 10) || 0;
  var b = parseInt((document.getElementById('f3') || {}).textContent, 10) || 0;
  root.classList.toggle('scoreboard-lead-a', a > b);
  root.classList.toggle('scoreboard-lead-b', b > a);
  var final = root.classList.contains('scoreboard-final');
  var status = document.querySelector('.scoreboard-status');
  if (status) status.textContent = final ? wordOf('f5', 'FINAL') : wordOf('f6', 'LIVE');
  var flags = document.querySelectorAll('.scoreboard-flag-word');
  for (var i = 0; i < flags.length; i++) flags[i].textContent = wordOf('f4', 'GOAL');
}

// resetOnTake(): Take puts the machine groups back to their start without playing their
// timelines, so the look a previous match left behind is cleared here.
function resetOnTake() {
  var root = document.querySelector('.scoreboard');
  if (root) { root.classList.remove('scoreboard-final'); root.classList.remove('scoreboard-break'); }
  paintBoard();
}

// play(): take the scoreboard on air""",1)
